parameters.jsCode:
const aiResponse = $input.first().json.output;

// Detectar si hay un JSON dentro de un bloque de código markdown
const jsonBlockMatch = aiResponse.match(/```json\s*([\s\S]*?)\s*```/);
const hasJson = jsonBlockMatch !== null;

// Variables para los comandos
let commandData = null;
let isComandoAceptar = false;
let isComandoContraofertar = false;
let isComandoEntregar = false;
let isComandoCambiarEstado = false;

// Extraer y procesar el JSON si existe
if (hasJson) {
    try {
        // Extraer solo el contenido JSON del bloque
        const jsonString = jsonBlockMatch[1].trim();
        commandData = JSON.parse(jsonString);

        // Detectar el tipo de comando basado en la propiedad "comando"
        if (commandData.comando) {
            switch (commandData.comando) {
                case 'aceptar':
                    isComandoAceptar = true;
                    break;

                case 'contraofertar':
                    isComandoContraofertar = true;
                    break;

                case 'entregar':
                    isComandoEntregar = true;
                    break;

                case 'cambiar_estado':
                    isComandoCambiarEstado = true;
                    break;
            }
        }

    } catch (error) {
        console.log('Error parsing JSON:', error);
        commandData = null;
    }
}

// Limpiar la respuesta para el cliente (quitar todo el bloque JSON)
let cleanResponse = aiResponse;
if (hasJson) {
    cleanResponse = aiResponse.replace(jsonBlockMatch[0], '').trim();
    // Quitar líneas vacías extra que puedan quedar
    cleanResponse = cleanResponse.replace(/\n\s*\n+/g, '\n\n').trim();
}

// Estructurar la salida
return [{
    output: cleanResponse,
    is_comando_aceptar: isComandoAceptar,
    is_comando_contraofertar: isComandoContraofertar,
    is_comando_entregar: isComandoEntregar,
    is_comando_cambiar_estado: isComandoCambiarEstado,
    command_data: commandData
}];
